mapper.insert:
INSERT INTO FILE_GROUP ( /* fileMapper.insertFileGroup => 파일 그룹 등록 */
    FILE_GRP_ID, FILE_PATH, RGTR_KEY, REG_DT, DEL_YN
) VALUES (
    #{fileGrpId}, #{filePath}, #{rgtrKey}, CURRENT_TIMESTAMP, 'N'
)

mapper.update:
UPDATE FILE_GROUP /* fileMapper.deleteFileGroup => 파일 그룹 삭제 */
SET DEL_YN = 'Y'
WHERE FILE_GRP_ID = #{fileGrpId}

UPDATE FILE_DETAIL /* fileMapper.deleteFileDetail => 파일 삭제 */
SET DEL_YN = 'Y', DEL_DT = CURRENT_TIMESTAMP
WHERE FILE_ID = #{fileId}

UPDATE FILE_DETAIL /* fileMapper.deleteAllFileDetail => 파일 그룹에 해당하는 파일 삭제 */
SET DEL_YN = 'Y', DEL_DT = CURRENT_TIMESTAMP
WHERE FILE_GRP_SEQ = #{fileGrpSeq}
